class MultiChoiceQuestionExtractAnswerOptions(SALTSelfTaughtSimpleSolutionVerify):
    MULTICHOICE_LETTER = ('A', 'B', 'C', 'D', 'E', 'F',
                          'G', 'H', 'I', 'J', 'K', 'L')

    def __init__(self):
        super().__init__()

    @classmethod
    def task_desc(cls):
        return "选择题提取答案"

    def prompt_fn(self, example):
        solver_response, extra, gt = example
        thought, question, options, ans = extra
        _question = Doc2QueryV3ComputeScore._format_question(
            question, Doc2QueryV3ComputeScore.add_distractor_options(
                options, gt), None
        )
        prompt = MULTICHOICE_EXTRACT_ANSWER_FEWSHOTS + "\n\n\n" + MULTICHOICE_EXTRACT_ANSWER_TEMPLATE.format(
            question=_question,
            conclusion=solver_response,
        )
        return prompt

    def postprocess(self, response: str):
        try:
            response = response.strip()
            try:
                conclusion = re.findall(r'\[.*?\]', response)[-1].strip()
                ans_list = eval(conclusion.strip())
            except Exception as err:
                raise PostprocessError(f'Parse Python List Failed')

            if not isinstance(ans_list, list):
                raise PostprocessError(f'Parse Python List Failed')
            if not all(_ans in self.MULTICHOICE_LETTER for _ans in ans_list):
                raise PostprocessError(f'Parse Python List Failed')
            return ans_list
        except Exception as err:
            raise PostprocessError(f'Parse Python List Failed')


class DocRefinementHonestyJudge(BatchCallOpenAPI):
    _TEMPLATE = REFINEMENT_HONESTY_JUDGE_TEMPLATE_ZH

    def __init__(self, repeat=1):
        self.repeat = repeat

    @classmethod
    def task_desc(cls):
        return "改写真实性"

    def postprocess(self, response: str):
        if random.random() < 0.005:
            print(f'[JUDGE EVAL] {self.task_desc()} {repr(response)}')
        # print(f'[JUDGE EVAL] {self.task_desc()} {repr(response)}')
        s = response
        try:
            conclusion = s.strip()
            judge = re.findall(
                r'\"judge\"\s*:\s*\"(.*)\"', conclusion)
            if len(judge) > 0 and judge[-1].lower() in ("true", "false"):
                return judge[-1].lower() == "true"
            raise PostprocessError(f'eval corrupt format')
        except Exception as err:
            pass

        try:
            conclusion = s.strip()
            judge = re.findall(
                r'\"judge\"\s*:\s*(.*)', conclusion)
            if len(judge) > 0 and judge[-1].lower() in ("true", "false"):
                return judge[-1].lower() == "true"
            raise PostprocessError(f'eval corrupt format')
        except Exception as err:
            raise PostprocessError(f'{err}')

    def prompt_fn(self, example):
        solver_response, gt = example
        prompt = self._TEMPLATE.format(
            raw=gt,
            refinement=solver_response
        )
        return prompt

    async def do_job(self, agent, batch_inputs, max_concurrent_requests):
        prompts = defaultdict(list)
        for index, example in enumerate(batch_inputs):
            prompt = self.prompt_fn(example)
            prompts[prompt].append(index)

        _prompts = list(prompts.keys()) * self.repeat
        results = await agent.run(_prompts, max_concurrent_requests, desc=f"[{self.task_desc()} {agent.model}={max_concurrent_requests}]", postprocess_fns=[self.postprocess]*len(_prompts))

        results_mapper = defaultdict(list)
        for (k, v) in results:
            for _ in prompts[k]:
                results_mapper[_].append(v)

        outputs = []
        for i, _ in enumerate(batch_inputs):
            if i in results_mapper and results_mapper[i] is not None:
                if isinstance(results_mapper[i], list):
                    outputs.append(all(results_mapper[i]))
                else:
                    outputs.append(results_mapper[i])
            else:
                outputs.append(None)
        return outputs


class DocRefinementHonestyFinegrainJudge(DocRefinementHonestyJudge):
    _TEMPLATE = REFINEMENT_HONESTY_FINEGRAIN_JUDGE_TEMPLATE_ZH

    def __init__(self):
        super().__init__()

    @classmethod
    def task_desc(cls):
        return "改写真实性(细粒度)"

    def postprocess(self, response: str):
        if random.random() < 0.005:
            print(f'[JUDGE EVAL] {self.task_desc()} {repr(response)}')
        # print(f'[JUDGE EVAL] {self.task_desc()} {repr(response)}')
        s = response
        try:
            conclusion = s.strip()
            judge = re.findall(
                r'\"score\":\s*(\d+)\s*', conclusion)
            if len(judge) > 0 and any(_ in judge[0] for _ in ("1", "2", "3", "4", "5")):
                try:
                    for _ in ("1", "2", "3", "4", "5"):
                        if _ in judge[-1]:
                            return max(min(float(int(_)/5.0), 1.0), 0.0)
                    raise PostprocessError(f'eval corrupt format') 
                except Exception as err:
                    raise PostprocessError(f'eval corrupt format') 
            raise PostprocessError(f'eval corrupt format')
        except Exception as err:
            raise PostprocessError(f'{err}')

    async def do_job(self, agent, batch_inputs, max_concurrent_requests):
        prompts = defaultdict(list)
        for index, example in enumerate(batch_inputs):
            prompt = self.prompt_fn(example)
            prompts[prompt].append(index)

        _prompts = list(prompts.keys()) * self.repeat
        results = await agent.run(_prompts, max_concurrent_requests, desc=f"[{self.task_desc()} {agent.model}={max_concurrent_requests}]", postprocess_fns=[self.postprocess]*len(_prompts))

        results_mapper = defaultdict(list)
        for (k, v) in results:
            for _ in prompts[k]:
                results_mapper[_].append(v)

        outputs = []
        for i, _ in enumerate(batch_inputs):
            if i in results_mapper and results_mapper[i] is not None:
                if isinstance(results_mapper[i], list):
                    scores = results_mapper[i]
                    scores = [_ for _ in scores if _ is not None]
                    if len(scores) > 0:
                        outputs.append(np.mean(scores))
                    else:
                        outputs.append(0.0)
                elif results_mapper[i] is None:
                    outputs.append(None)
                else:
                    outputs.append(results_mapper[i])
            else:
                outputs.append(None)
        return outputs


