class KDRewriteAtomicityJudge(DocRefinementHonestyJudge):
    _TEMPLATE = KNOWLEDGE_DISTILL_RUBRIC_ATOMICITY_TEMPLATE_ZH

    def __init__(self):
        super().__init__()

    @classmethod
    def task_desc(cls):
        return "原子性"

    def prompt_fn(self, example):
        content, gt = example
        prompt = self._TEMPLATE.format(
            content=content
        )
        return prompt

    def postprocess(self, response: str):
        if random.random() < 0.0005:
            print(f'[JUDGE EVAL] {self.task_desc()} {repr(response)}')
        s = response
        try:
            conclusion = s.strip()
            judge = re.findall(r'(\d+)', conclusion)
            if len(judge) > 0 and any(_ in judge[0] for _ in ("1", "2", "3")):
                judge = judge[0]
                if judge == "1":
                    return 0
                elif judge == "2":
                    return 0.5
                else:
                    return 1

            raise PostprocessError(f'eval corrupt format')
        except Exception as err:
            raise PostprocessError(f'{err}')

    async def do_job(self, agent, batch_inputs, max_concurrent_requests):
        prompts = defaultdict(list)
        for index, example in enumerate(batch_inputs):
            prompt = self.prompt_fn(example)
            prompts[prompt].append(index)

        _prompts = list(prompts.keys()) * self.repeat
        results = await agent.run(_prompts, max_concurrent_requests, desc=f"[{self.task_desc()} {agent.model}={max_concurrent_requests}]", postprocess_fns=[self.postprocess]*len(_prompts))

        results_mapper = defaultdict(list)
        for (k, v) in results:
            for _ in prompts[k]:
                results_mapper[_].append(v)

        outputs = []
        for i, _ in enumerate(batch_inputs):
            if i in results_mapper and results_mapper[i] is not None:
                if isinstance(results_mapper[i], list):
                    outputs.append(results_mapper[i][0])
                else:
                    outputs.append(results_mapper[i])
            else:
                outputs.append(None)
        return outputs


