class CLRewriteSimilarityJudge(JudgeTwoQuestionSimilarity):
    _TEMPLATE = CONTEXT_LEARNING_REWRITE_JUDGE_SIMILARITY_TEMPLATE

    def __init__(self):
        super().__init__()

    @classmethod
    def task_desc(cls):
        return "相似度"

    def prompt_fn(self, example):
        content, gt = example
        prompt = self._TEMPLATE.format(
            content1=content,
            content2=gt
        )
        return prompt

    def postprocess(self, response: str):
        s = response
        try:
            conclusion = s
            conclusion = conclusion[conclusion.index(
                "[CONCLUSION START]")+len("[CONCLUSION START]"):conclusion.index("[CONCLUSION END]")].strip()

            score = int(re.findall(r'SIMILARITY=(\d+)', conclusion)[0].strip())
            if score not in (1, 2, 3, 4, 5):
                raise PostprocessError(f'invalid similarity score={score}')
            return score / 5.0
        except Exception as err:
            raise PostprocessError(f'{err}')


class CLRewriteRubricsOverlapJudge(DocRefinementHonestyJudge):
    _TEMPLATE = CONTEXT_LEARNING_REWRITE_RUBRICS_OVERLAP_JUDGE_TEMPLATE

    def __init__(self, repeat=1):
        self.repeat = repeat

    @classmethod
    def task_desc(cls):
        return "Overlap"

    def postprocess(self, response: str):
        if random.random() < 0.005:
            print(f'[JUDGE EVAL] {self.task_desc()} {repr(response)}')
        s = response
        try:
            conclusion = s.strip()
            judge = re.findall(
                r'\"judge\"\s*:\s*\"(.*)\"', conclusion)
            if len(judge) > 0 and judge[-1].lower() in ("true", "false"):
                return judge[-1].lower() == "false"
            raise PostprocessError(f'eval corrupt format')
        except Exception as err:
            pass

        try:
            conclusion = s.strip()
            judge = re.findall(
                r'\"judge\"\s*:\s*(.*)', conclusion)
            if len(judge) > 0 and judge[-1].lower() in ("true", "false"):
                return judge[-1].lower() == "false"
            raise PostprocessError(f'eval corrupt format')
        except Exception as err:
            raise PostprocessError(f'{err}')

    def prompt_fn(self, example):
        solver_response, gt = example
        prompt = self._TEMPLATE.format(
            rubrics=solver_response
        )
        return prompt


