def rlvr_longcot_parse_thought_and_conclusion_fn(solution_str: str, remove_option_letter=True):
    solution_str = postprocess_solution(solution_str)

    if not solution_str.startswith("<think>"):
        solution_str = f'<think>\n{solution_str}'

    try:
        thought = re.findall(r'<think>.*</think>',
                             solution_str, re.DOTALL)[0]
    except Exception as err:
        return None, None

    solution_str = solution_str.replace(thought, "")
    return thought, solution_str


def rlvr_longcot_parse_solution_fn(solution_str: str, remove_option_letter=True):
    solution_str = postprocess_solution(solution_str)

    if not solution_str.startswith("<think>"):
        solution_str = f'<think>\n{solution_str}'

    try:
        thought = re.findall(r'<think>.*</think>',
                             solution_str, re.DOTALL)[0]
    except Exception as err:
        return None

    solution_str = solution_str.replace(thought, "").strip()
    return solution_str


class RLVRComputeScore(Doc2QueryV2ComputeScore):
    def __init__(self,
                 parse_solution_fn,
                 split="train",
                 args=None,
                 min_reward=-2.0,
                 ):

        super().__init__(
            split=split,
            args=args,
            min_reward=min_reward,
            parse_solution_fn=parse_solution_fn
        )
        self.task_name = "RLVR"

    def init_agent(self):
        self.agents = {}
        self.init_verify_agent()

    def init_verify_agent(self):
        self.verify_agent = Agent(
            **self.args["verify_agent"]["model"])
        self.agents["rlvr"] = self.verify_agent

    def response_postprocess(self, response: str):
        s = response
        if "</think>" in s:
            s = s[s.index("</think>")+len("</think>"):]
        return s

    async def get_accuracy(
            self,
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth):

        task = RLVRVerify()

        indices = []
        eval_inputs = []
        result_index2queue_index = {}
        for i, (gt, sol) in enumerate(zip(batch_ground_truth, batch_solution_str)):
            result = self.parse_solution_fn(sol)
            if result is not None:
                eval_inputs.append((result, gt))
                indices.append(i)
                result_index2queue_index[len(
                    eval_inputs)-1] = i
            else:
                continue

        evaluations = await task.do_job(
            agent=self.verify_agent,
            batch_inputs=eval_inputs,
            max_concurrent_requests=self.args["verify_agent"]["max_concurrent_requests"],
        )

        full_rewards = [self.min_reward] * len(batch_solution_str)
        for j, (eval_result, eval_input) in enumerate(zip(evaluations, eval_inputs)):
            queue_index = result_index2queue_index[j]
            if eval_result:
                full_rewards[queue_index] = 1.0
            else:
                full_rewards[queue_index] = 0.0
        return full_rewards

    def clip_string(self, s: str):
        if len(s) > 1500:
            return f'{s[:700]}... [省略] ...{s[-800:]}'
        return s

    def log_solution(self, solution, **kwargs):
        norm = self.parse_solution_fn(solution)
        if norm is None:
            return repr(self.clip_string(solution.strip()))
        return repr(norm)

    async def _compute_score(self,
                             batch_data_sources,
                             batch_solution_str,
                             batch_ground_truth,
                             ):
        accuracy = await self.get_accuracy(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
        )

        final_results = []
        for i in range(len(batch_solution_str)):
            _reward = accuracy[i]
            final_results.append(_reward)

            if (_reward > 0 and random.random() < 0.1) or (self.split == "valid" and random.random() < 0.05) or (self.split == "train" and random.random() < 0.05):
                log = True
                log_flag = f"[{self.task_name} VALID]" if self.split == "valid" else f"[{self.task_name} TRAIN]"
            else:
                log = False

            if log:
                print(
                    f"--------------------------------{log_flag}--------------------------------")
                print(
                    f'【Question】`{repr(batch_ground_truth[i]["prompt"])}`')
                print(
                    f"【Solution】`{self.log_solution(batch_solution_str[i])}`")
                try:
                    print(
                        f'【Ground Truth】`{batch_ground_truth[i]["ground_truth"]}`')
                except Exception as err:
                    pass
                print(
                    f'[Final Reward]={_reward:.3f}\n')

        return final_results


