def doc2query_v4_parse_solution_fn(solution_str: str, remove_option_letter=True, extract_question_fn=parse_question_solution_fn):
    for kw in ("</doc>", "</question>"):
        if solution_str.count(kw) > 1:
            return None

    solution_str = postprocess_solution(solution_str)
    try:
        question = re.findall(r'<question>.*?</question>',
                             solution_str, re.DOTALL)[0]
    except Exception as err:
        return None

    solution_str = solution_str.replace(question, "")

    try:
        doc = re.findall(r'<doc>(.*)</doc>',
                         solution_str, re.DOTALL)[0].strip()
    except Exception as err:
        return None
    if len(question) == 0:
        return None
    if not any(_ in question for _ in ("你是", "You are")):
        return None

    if any(exclude_kw in question for exclude_kw in (
        "***", "{具体身份", '{身份信息}', '{写作背景}', '{写作动机}', '{Thinking process', '{创作过程', "[Your Name]", "[Specific Research",
        "{{具体身份", "{{", "}}")):
        return None

    if any(exclude_kw in question for exclude_kw in ("引用", "原文")):
        return None

    return question, "", doc


class Doc2QueryV4ComputeScore(Doc2QueryV3ComputeScore):

    def __init__(self,
                 parse_solution_fn,
                 split="train",
                 args=None,
                 min_reward=-5.0,
                 thought_log_prob=0.03,
                 parse_thought_and_conclusion_fn=doc2query_v4_parse_solution_fn,
                 ):
        super().__init__(
            parse_solution_fn=parse_solution_fn, split=split,
            args=args,
            min_reward=min_reward,
            thought_log_prob=thought_log_prob
        )
        self.task_name = "DOC2QUERY_V4"
        self.scorer = rouge_scorer.RougeScorer(['rougeL'], use_stemmer=True)

    def init_agent(self):
        self.agents = {}
        self.init_verify_agent()

    def init_verify_agent(self):
        self.verify_agent = Agent(
            **self.args["verify_agent"]["model"])

    @classmethod
    def rule_based_penalties(cls):
        return []

    def init_rule_based_penalties(self):
        self._penalties = []

    async def eval_on_doc(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        eval_task,
        min_score,
        max_score
    ):
        task = eval_task
        indices = []
        questions = []

        for i, (gt, sol) in enumerate(zip(batch_ground_truth, batch_solution_str)):
            result = self.parse_solution_fn(sol)
            if result is not None:
                thought, inner_voice, refined_doc = result
                raw_doc = gt["document"]
                questions.append((refined_doc, raw_doc))
                indices.append(i)
            else:
                continue

        repeat_questions = questions
        repeat_indices = indices

        qualities = await task.do_job(
            agent=self.verify_agent,
            batch_inputs=repeat_questions,
            max_concurrent_requests=self.args["verify_agent"]["max_concurrent_requests"],
        )

        scores = []
        for i in range(len(batch_solution_str)):
            scores.append([])
        for valid, index in zip(qualities, repeat_indices):
            if valid is None:
                pass
            else:
                _score = max_score if valid else min_score
                scores[index].append(_score)

        final_scores = [0.0] * len(batch_solution_str)
        for i, score in enumerate(scores):
            if len(score) == 0:
                final_scores[i] = 0.0
            else:
                final_scores[i] = min(score)
        return final_scores

    async def model_judge(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
    ):
        return await self.eval_on_doc(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=Doc2QueryV4ModelJudgeDoc(),
            min_score=-1.0,
            max_score=1.0,
        )

    async def contain_critical_keywords(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None,
    ):
        """
        包含关键信息
        """
        outputs = [0.0] * len(batch_solution_str)
        for i, (sol, gt) in enumerate(zip(batch_solution_str, batch_ground_truth)):
            parsed = self.parse_solution_fn(sol)

            score = 0.0
            if parsed is not None:
                question = parsed[0]
                question = question.strip().lower()
                    
                if question.startswith("你是") or question.startswith("you are"):
                    score += 0.5
                if "<think>" not in question and "</think>" not in question:
                    score += 0.5

            outputs[i] += score
        return outputs

    async def info_overlap(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None,
        max_sim_threshold=0.5,
        weight=2.0,
    ):
        """
        信息增益
        """
        outputs = [0.0] * len(batch_solution_str)
        for i, (sol, gt) in enumerate(zip(batch_solution_str, batch_ground_truth)):
            parsed = self.parse_solution_fn(sol)

            if parsed is not None:
                thought, refined_doc = parsed[1], parsed[2]
                lang_code = "zh" if contain_chinese(refined_doc) else "en"

                hyp_tokens = " ".join(tokenize(thought.lower(), lang_code))
                ref_tokens = " ".join(tokenize(refined_doc.lower(), lang_code))

                info_overlap = sacrebleu.sentence_bleu(
                    hyp_tokens, [ref_tokens]).score / 100

                outputs[i] += (-info_overlap * weight)

        return outputs

    def get_coverage_score(self, thought_tokens, ref_tokens, weight=2.0):
        score = self.scorer.score(ref_tokens, thought_tokens)
        rouge_recall = score["rougeL"].fmeasure

        return rouge_recall * weight

    async def rule_judge(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None,
        min_score=-5.0,
        max_score=5.0,
        threshold=0.8
    ):

        def is_code_content(s):
            if s.count("import") > 1:
                if all(kw in s for kw in ("= ","for ","if ", "def ",)):
                    return True
            return False

        outputs = [0.0] * len(batch_solution_str)
        for i, (sol, gt) in enumerate(zip(batch_solution_str, batch_ground_truth)):
            parsed = self.parse_solution_fn(sol)

            if parsed is not None:
                thought, refined_doc, raw_doc = parsed[0], parsed[2], gt["document"]
                lang_code = "zh" if contain_chinese(raw_doc) else "en"

                thought_tokens = " ".join(tokenize(thought.lower(), lang_code))
                hyp_tokens = " ".join(tokenize(refined_doc.lower(), lang_code))
                ref_tokens = " ".join(tokenize(raw_doc.lower(), lang_code))

                info = sacrebleu.sentence_bleu(
                    hyp_tokens, [ref_tokens]).score / 100

                coverage_score = self.get_coverage_score(
                    thought_tokens, ref_tokens, weight=10.0
                )
                try:
                    size_ratio = len(hyp_tokens) / len(ref_tokens)
                except Exception as err:
                    size_ratio = 1.0

                # 代码检测
                if is_code_content(raw_doc):
                    code_stuff = re.findall(r'```(.*?)```', thought, re.DOTALL)
                    if len(code_stuff) == 0:
                        outputs[i] += min_score
                        continue

                if size_ratio < threshold or size_ratio > (2-threshold):
                    outputs[i] += min_score
                else:
                    if info > threshold:
                        outputs[i] += max_score + coverage_score
                    else:
                        outputs[i] += min_score
        return outputs

    @classmethod
    def rule_based_penalties(cls):
        return [
            LanguageConsistency,
        ]

    def coarse_process(self):
        return [
            # Process(name="ModelJudge",
            #         function=self.model_judge, filter_only=False, non_skip=True),
            Process(name="Keywords", function=self.contain_critical_keywords, filter_only=False, non_skip=True)
        ]

    def finegrain_process(self):
        return Process(name="RuleJudge",
                       function=self.rule_judge, filter_only=False, non_skip=False)

    @classmethod
    def respond(cls, result, gt):
        return result[0]

    def clip_string(self, s: str):
        if len(s) > 8000:
            return f'{s[:4000]}... [省略] ...{s[-4000:]}'
        return s

    def log_solution(self, solution, **kwargs):
        norm = self.parse_solution_fn(solution)
        if norm is not None:
            return f'[INNER_VOICE]({len(norm[1])}) `{repr(self.clip_string(norm[1]))}` --------------- [DOC]({len(norm[2])}) `{repr(self.clip_string(norm[2]))}`'
        else:
            return repr(self.clip_string(solution))

    async def _compute_score(self,
                             batch_data_sources,
                             batch_solution_str,
                             batch_ground_truth,
                             ):        
        penalty = defaultdict(list)
        for i, (data_source, solution_str, ground_truth) in enumerate(zip(batch_data_sources, batch_solution_str, batch_ground_truth)):
            parsed = self.parse_solution_fn(solution_str)
            if parsed is None:
                penalty[i].append(self.min_reward)
            else:
                penalty[i].append(0.0)

            for p in self._penalties:
                penalty[i].append(p.get_penalty_or_reward(
                    solution_str, ground_truth))

        all_skip_next_action = []

        minor_rewards = OrderedDict()
        all_minor_rewards = OrderedDict()

        for process in self.coarse_process():
            process_eval = await process.function(
                batch_data_sources,
                batch_solution_str,
                batch_ground_truth,
            )
            # do skipping
            if not process.non_skip:
                skip_next_action = [
                    i for i, v in enumerate(process_eval) if v < 0.0]
                all_skip_next_action.extend(skip_next_action)

            if not process.filter_only:
                minor_rewards[process.name] = process_eval
            all_minor_rewards[process.name] = process_eval

        all_skip_next_action = sorted(list(set(all_skip_next_action)))
        all_skip_next_action = tuple(all_skip_next_action)

        main_process = self.finegrain_process()
        main_rewards = await main_process.function(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            skip_run=all_skip_next_action,
        )
        final_results = []

        main_reward_pos = None  # 记录主奖励位置
        for i in range(len(batch_solution_str)):
            scores = copy.deepcopy(penalty[i])
            penalties = ["Parse"]+[_.abbrev for _ in self._penalties]
            penalty_log_str = "/".join([f'{p}={s:.3f}' for p,
                                        s in zip(penalties, scores)])

            _main_reward = main_rewards[i]
            _main_reward = np.sum(_main_reward) if isinstance(
                _main_reward, list) else _main_reward
            scores.append(_main_reward)

            main_reward_pos = len(scores) - 1

            for name, v in minor_rewards.items():
                scores.append(v[i])

            cur_score = 0

            for j, _score in enumerate(scores):
                if _score < 0:
                    if j < main_reward_pos:
                        cur_score = _score
                        break
                    else:
                        cur_score += _score
                else:
                    cur_score += _score

            final_results.append(cur_score)

            log_flag = f"[{self.task_name} VALID]" if self.split == "valid" else f"[{self.task_name} TRAIN]"
            if _main_reward > 0 or (self.split == "valid" and random.random() < self.thought_log_prob) or (self.split == "train" and random.random() < self.thought_log_prob):
                log = True
            else:
                log = False
                
            if cur_score == self.min_reward and random.random() < self.thought_log_prob:
                log = True
                log_flag = f"[{self.task_name} VALID CORRUPT RESPONSE]" if self.split == "valid" else f"[{self.task_name} TRAIN CORRUPT RESPONSE]"

            source = batch_ground_truth[i]["source"]

            _minor_rewards_log = []
            for process in self.coarse_process():
                _minor_rewards_log.append(
                    f'{process.name}={all_minor_rewards[process.name][i]}')
            _minor_rewards_log = "|".join(_minor_rewards_log)
            if log:
                print(f'【Solution{i}】[Final Reward]={cur_score:.3f}|{main_process.name}={str(_main_reward)}|{_minor_rewards_log}|{penalty_log_str} ----- {self.log_solution(batch_solution_str[i], gt=batch_ground_truth[i])}')

        return final_results

