def doc2query_v5_parse_solution_fn(solution_str: str, remove_option_letter=True, extract_question_fn=parse_question_solution_fn):
    for kw in ("</doc>", "</think>"):
        if solution_str.count(kw) > 1:
            return None
            
    solution_str = postprocess_solution(solution_str)
    if not solution_str.startswith("<think>"):
        solution_str = f'<think>\n{solution_str}'

    try:
        thought = re.findall(r'<think>(.*?)</think>',
                             solution_str, re.DOTALL)[0]
    except Exception as err:
        return None

    inner_voice = thought

    if len(inner_voice) < 200:
        return None

    solution_str = solution_str.replace(thought, "")
    doc = solution_str.replace("<doc>", "").replace("</doc>", "").replace("<think>", "").replace("</think>", "").strip()

    inner_voice = inner_voice.strip()
    return thought, inner_voice, doc


class Doc2QueryV5ComputeScore(Doc2QueryV4ComputeScore):

    def __init__(self,
                 parse_solution_fn,
                 split="train",
                 args=None,
                 min_reward=-10.0,
                 thought_log_prob=0.05,
                 parse_thought_and_conclusion_fn=doc2query_v5_parse_solution_fn,
                 ):
        super().__init__(
            parse_solution_fn=parse_solution_fn, split=split,
            args=args,
            min_reward=min_reward,
            thought_log_prob=thought_log_prob
        )
        self.task_name = "DOC2QUERY_V5"

    @classmethod
    def calc_qa_coverage(
        cls, thought,
    ):
        qa_content = re.findall(r"Q: (.*?)\nA: (.*?)(?=\nQ: |\Z)", thought, re.DOTALL | re.MULTILINE)
        qa_content_size = 0
        for _ in qa_content:
            qa_content_size += len(_[0]) + len(_[1])
        return qa_content_size / len(thought)

    async def contain_critical_keywords(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None,
    ):
        """
        包含关键信息
        """
        outputs = [0.0] * len(batch_solution_str)
        for i, (sol, gt) in enumerate(zip(batch_solution_str, batch_ground_truth)):
            parsed = self.parse_solution_fn(sol)

            score = 0.0
            if parsed is not None:
                thought, doc = parsed[1], parsed[2]
                qa_coverage = self.calc_qa_coverage(thought)
                thought = thought.strip().lower()
                
                score = 0.0
                
            outputs[i] += score
        return outputs

    def log_ground_truth(self, ground_truth):
        print(f'[QUESTION]({len(ground_truth["question"])})\n{repr(ground_truth["question"])}\n')


