def doc2query_v6_refine_parse_solution_fn(solution_str: str):
    def detect_zh_ratio(text):
        if text is None:
            return None
        # Remove URLs, numbers, and punctuation to focus on language characters
        cleaned_text = re.sub(r'[^\w\s]|[\d]', '', text)
        if not cleaned_text:
            return False

        # Count Chinese characters
        chinese_chars = re.findall(r'[\u4e00-\u9fa5]', cleaned_text)
        chinese_count = len(chinese_chars)

        # Count English characters
        english_chars = re.findall(r'[a-zA-Z]', cleaned_text)
        english_count = len(english_chars)

        # Total language characters
        total_chars = chinese_count + english_count
        if total_chars == 0:
            return False

        # Calculate ratios
        chinese_ratio = chinese_count / total_chars
        english_ratio = english_count / total_chars

        # Check if both languages exceed the threshold
        return chinese_ratio

    def _parse(s):
        raw_str = s
        try:
            title = re.findall(r'<title>.*?</title>', s, re.DOTALL)[0].strip()
        except Exception as err:
            return None
        
        s = s.replace(title, "")

        try:
            conception = re.findall(r'<conception>.*?</conception>', s, re.DOTALL)[0].strip()
        except Exception as err:
            return None
        
        s = s.replace(conception, "")

        try:
            document = re.findall(r'<doc>.*?</doc>', s, re.DOTALL)[0].strip()
        except Exception as err:
            return None
        
        s = s.replace(document, "").strip()
        if len(s) > 0:
            return None
        return title, conception, document

    parsed = _parse(solution_str)
    if parsed is None:
        return None
    
    conception, document = parsed[1], parsed[2]
    if detect_zh_ratio(conception) > 0.4:
        if detect_zh_ratio(document) < 0.4:
            return None
    else:
        if detect_zh_ratio(document) > 0.4:
            return None

    return parsed[1], parsed[2], solution_str


class Doc2QueryV6RefineComputeScore(Doc2QueryV6ComputeScore):
    def __init__(self,
                 parse_solution_fn,
                 split="train",
                 args=None,
                 min_reward=-2.0,
                 thought_log_prob=0.05,
                 parse_thought_and_conclusion_fn=doc2query_v6_refine_parse_solution_fn,
                 ):
        super().__init__(
            parse_solution_fn=parse_solution_fn, split=split,
            args=args,
            min_reward=min_reward,
            thought_log_prob=thought_log_prob
        )
        self.task_name = "DOC2QUERY_V6_REFINE"

    def init_agent(self):
        self.init_low_reason_agent()
        self.init_medium_reason_agent()

    def init_low_reason_agent(self):
        self.low_reason_agent = Agent(**self.args["low_reason_effort_agent"]["model"])

    def init_medium_reason_agent(self):
        self.medium_reason_agent = Agent(**self.args["medium_reason_effort_agent"]["model"])

    async def refinement_judge(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        eval_task,
        min_score,
        max_score,
        eval_agent,
        max_concurrent_requests,
        score_type="bool",
        judge_object="all",
        extra_object="original_document"
    ):
        task = eval_task
        indices = []
        pairs = []

        for i, (gt, sol) in enumerate(zip(batch_ground_truth, batch_solution_str)):
            result = self.parse_solution_fn(sol)
            if result is not None:
                conception, only_refined_doc, refined_doc = result
                if extra_object == "original_document":
                    obj = gt["original_document"]
                elif extra_object == "self_ask":
                     obj = gt["extra_info"]["self_ask"]
                else:
                    raise NotImplementedError(f'Unknown extra object `{extra_object}`')
                if judge_object == "all":
                    pairs.append((refined_doc, obj))
                elif judge_object == "conception":
                    pairs.append((conception, obj))
                else:
                    raise NotImplementedError
                indices.append(i)
            else:
                continue

        repeat_pairs = pairs
        repeat_indices = indices

        qualities = await task.do_job(
            agent=eval_agent,
            batch_inputs=repeat_pairs,
            max_concurrent_requests=max_concurrent_requests,
        )

        scores = []
        for i in range(len(batch_solution_str)):
            scores.append([])
        for valid, index in zip(qualities, repeat_indices):
            if valid is None:
                pass
            else:
                if score_type == "bool":
                    _score = max_score if valid else min_score
                elif score_type == "float":
                    _score = valid
                else:
                    raise NotImplementedError(f'Invalid critique score type {score_type}')
                scores[index].append(_score)

        final_scores = [0.0] * len(batch_solution_str)
        for i, score in enumerate(scores):
            if len(score) == 0:
                final_scores[i] = 0.0
            else:
                final_scores[i] = min(score)
        return final_scores

