    async def reason_depth_judge(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
    ):
        return await self.refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=DocRefinementReasonDepthJudge(),
            min_score=0,
            max_score=1.,
            eval_agent=self.low_reason_agent,
            max_concurrent_requests=self.args['medium_reason_effort_agent']["max_concurrent_requests"]
        )

    def log_solution(self, solution, **kwargs):
        gt = kwargs["gt"]
        norm = self.parse_solution_fn(solution)
        if norm is not None:
            return f'[REFINE]({len(norm[2])}) `{repr(norm[2])}` --------------- [RAW]({len(gt["original_document"])}) `{repr(gt["original_document"])}`'
        else:
            return repr(self.clip_string(solution))

    async def _compute_score(self,
                             batch_data_sources,
                             batch_solution_str,
                             batch_ground_truth,
                             ):       
        def left_candidates(s, skip_run):
            return [x for i, x in enumerate(s) if i not in skip_run]

        # Full Scoring Pipeline
        final_results = [0.0 for _ in range(len(batch_solution_str))]
        skip_run = set()

        # Base Penalty
        penalty = defaultdict(list)
        for i, (data_source, solution_str, ground_truth) in enumerate(zip(batch_data_sources, batch_solution_str, batch_ground_truth)):
            parsed = self.parse_solution_fn(solution_str)
            if parsed is None: # Failure
                final_results[i] = self.min_reward
                skip_run.add(i)
            else:
                final_results[i] = 0.0

        minor_rewards = OrderedDict()

        for process in [
            Process(name="Critical", function=self.critical_judge, filter_only=False, non_skip=False),
            Process(name="Redundency", function=self.judge_redundency, filter_only=False, non_skip=False),
            Process(name="SelfAskCoverage", function=self.judge_self_ask_coverage_finegrain, filter_only=False, non_skip=False),
            Process(name="ConceptionClarity", function=self.judge_conception_clarity, filter_only=False, non_skip=False),
            Process(name="ConceptionAesthetics", function=self.judge_conception_aesthetics, filter_only=False, non_skip=False),
            Process(name="HonestyFinegrain", function=self.judge_honesty_finegrain, filter_only=False, non_skip=False),
            Process(name="HelpfulFinegrain", function=self.judge_helpful_finegrain, filter_only=False, non_skip=False),
            Process(name="Honesty", function=self.judge_honesty, filter_only=False, non_skip=False),
            Process(name="Helpfulness", function=self.judge_helpfulness, filter_only=False, non_skip=False),
            Process(name="ReasonDepth", function=self.reason_depth_judge, filter_only=False, non_skip=True),
        ]:  
            tmp_batch_data_sources, tmp_batch_solution_str, tmp_batch_ground_truth = left_candidates(batch_data_sources, skip_run), \
                    left_candidates(batch_solution_str, skip_run), left_candidates(batch_ground_truth, skip_run)
            idx_mapper = [i for i in range(len(batch_ground_truth)) if i not in skip_run]
            idx_mapper = {j: _ for j, _ in enumerate(idx_mapper)}

            process_eval = await process.function(
                tmp_batch_data_sources,
                tmp_batch_solution_str,
                tmp_batch_ground_truth,
            )
            scores = [0.0] * len(batch_solution_str)

            for i, val in enumerate(process_eval):
                if val <= 0:
                    skip_run.add(idx_mapper[i])
                final_results[idx_mapper[i]] += val
                scores[idx_mapper[i]] = val

            minor_rewards[process.name] = scores

        for i in range(len(batch_solution_str)):
            cur_score = final_results[i]
            log_flag = f"[{self.task_name} VALID]" if self.split == "valid" else f"[{self.task_name} TRAIN]"
            if cur_score > 0 or (self.split == "valid" and random.random() < self.thought_log_prob) or (self.split == "train" and random.random() < self.thought_log_prob):
                log = True
            else:
                log = False
                
            if cur_score == self.min_reward and random.random() < self.thought_log_prob:
                log = True
                log_flag = f"[{self.task_name} VALID CORRUPT RESPONSE]" if self.split == "valid" else f"[{self.task_name} TRAIN CORRUPT RESPONSE]"

            source = batch_ground_truth[i]["source"]

            if log:
                _minor_rewards_log = []
                for k, v in minor_rewards.items():
                    _minor_rewards_log.append(
                        f'{k}={v[i]}')
                _minor_rewards_log = "|".join(_minor_rewards_log)
                print(f'【Solution{i}】[{batch_ground_truth[i]["extra_info"]["domain"]}] [Final Reward]={cur_score:.3f}|{_minor_rewards_log}| ----- {self.log_solution(batch_solution_str[i], gt=batch_ground_truth[i])}')

        return final_results

