def kd_rewrite_parse_solution_fn(solution_str: str):
    solution_str = postprocess_solution(solution_str)
    try:
        solution_str = solution_str[solution_str.index("```json")+len("```json"):].strip()
        solution_str = solution_str[:solution_str.index("```")].strip()
        content = json.loads(solution_str)

        for item in content:
            assert "content" in item and isinstance(item["content"], str)
            assert "fact" in item and isinstance(item["fact"], bool)
            assert "weight" in item and isinstance(item["weight"], int)
            if not item["fact"]:
                assert item["weight"] == 0
            else:
                assert item["weight"] in (1, 2, 3, 4, 5)

            if item["weight"] >= 2:
                assert len(item["qas"]) >= 1 and len(item["qas"]) <= 2
            if "qas" in item:
                assert isinstance(item["qas"], list)
                assert all(("question" in _) and ("answer" in _) for _ in item["qas"])
                assert len(item["qas"]) <= 2

    except Exception as err:
        return None
    
    return content
    

class KDRewriteComputeScore(Doc2QueryV3ComputeScore):
    def __init__(self,
                 parse_solution_fn,
                 split="train",
                 args=None,
                 min_reward=-2.0,
                 thought_log_prob=0.01,
                 ):
        super().__init__(
            parse_solution_fn=parse_solution_fn, split=split,
            args=args,
            min_reward=min_reward,
            thought_log_prob=thought_log_prob
        )
        self.task_name = "KD_REWRITE"

    def init_agent(self):
        self.agents = {}
        self.medium_reason_verify_agent = Agent(
            **self.args["medium_reason_verify_agent"]["model"])
        self.low_reason_verify_agent = Agent(
            **self.args["low_reason_verify_agent"]["model"])

    async def full_refinement_judge(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        eval_task,
        min_score,
        max_score,
        eval_agent,
        max_concurrent_requests,
        score_type="bool",
        judge_object=None,
        pair_parse_fn=lambda x, y: (" ".join([_["content"] for _ in x]), y["document"])
    ):
        task = eval_task
        indices = []
        pairs = []

        for i, (gt, sol) in enumerate(zip(batch_ground_truth, batch_solution_str)):
            result = self.parse_solution_fn(sol)
            if result is not None:
                pairs.append(pair_parse_fn(result, gt))
                # pairs.append((" ".join([_["content"] for _ in result]), gt["document"]))
                indices.append(i)
            else:
                continue

        repeat_pairs = pairs
        repeat_indices = indices

        qualities = await task.do_job(
            agent=eval_agent,
            batch_inputs=repeat_pairs,
            max_concurrent_requests=max_concurrent_requests,
        )

        scores = []
        for i in range(len(batch_solution_str)):
            scores.append([])
        for valid, index in zip(qualities, repeat_indices):
            if valid is None:
                pass
            else:
                if score_type == "bool":
                    _score = max_score if valid else min_score
                elif score_type == "float":
                    _score = valid
                else:
                    raise NotImplementedError(f'Invalid critique score type {score_type}')
                scores[index].append(_score)

        final_scores = [0.0] * len(batch_solution_str)
        for i, score in enumerate(scores):
            if len(score) == 0:
                final_scores[i] = 0.0
            else:
                final_scores[i] = min(score)
        return final_scores

    async def split_refinement_judge(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        eval_task,
        min_score,
        max_score,
        eval_agent,
        max_concurrent_requests,
        score_type="bool",
        judge_object=None,
        gt_key="document"
    ):
        task = eval_task
        indices = []
        pairs = []

        for i, (gt, sol) in enumerate(zip(batch_ground_truth, batch_solution_str)):
            result = self.parse_solution_fn(sol)
            if result is not None:
                for j, _ in enumerate(result):
                    pairs.append((_, gt[gt_key]))
                    indices.append(i)
            else:
                continue

        qualities = await task.do_job(
            agent=eval_agent,
            batch_inputs=pairs,
            max_concurrent_requests=max_concurrent_requests,
        )

        scores = []
        for i in range(len(batch_solution_str)):
            scores.append([])
        for valid, index in zip(qualities, indices):
            if valid is None:
                pass
            else:
                if score_type == "bool":
                    _score = max_score if valid else min_score
                elif score_type == "float":
                    _score = valid
                else:
                    raise NotImplementedError(f'Invalid critique score type {score_type}')
                scores[index].append(_score)

        return scores

    async def judge_with_kill_criteria(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None,
    ):
        return await self.full_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=KDRewriteCriticalJudge(),
            min_score=0.,
            max_score=1.0,
            eval_agent=self.medium_reason_verify_agent,
            max_concurrent_requests=self.args['medium_reason_verify_agent']["max_concurrent_requests"],
            score_type="bool",
        )

    async def judge_atomicity(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        return await self.split_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=KDRewriteAtomicityJudge(),
            min_score=0.,
            max_score=1.0,
            eval_agent=self.low_reason_verify_agent,
            max_concurrent_requests=self.args['low_reason_verify_agent']["max_concurrent_requests"],
            score_type="float",
        )

    async def judge_independency(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        return await self.split_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=KDRewriteIndependencyJudge(),
            min_score=0.,
            max_score=1.0,
            eval_agent=self.low_reason_verify_agent,
            max_concurrent_requests=self.args['low_reason_verify_agent']["max_concurrent_requests"],
            score_type="bool",
        )

    async def judge_nli(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        return await self.split_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=KDRewriteNLIJudge(),
            min_score=0.,
            max_score=1.0,
            eval_agent=self.low_reason_verify_agent,
            max_concurrent_requests=self.args['low_reason_verify_agent']["max_concurrent_requests"],
            score_type="bool",
        )

    async def judge_fact_and_weight(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        return await self.split_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=KDRewriteFactAndWeightJudge(),
            min_score=0.,
            max_score=1.0,
            eval_agent=self.low_reason_verify_agent,
            max_concurrent_requests=self.args['low_reason_verify_agent']["max_concurrent_requests"],
            score_type="bool",
        )

    async def judge_qa_quality(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        return await self.split_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=KDRewriteQAQualityJudge(),
            min_score=0.,
            max_score=1.0,
            eval_agent=self.low_reason_verify_agent,
            max_concurrent_requests=self.args['low_reason_verify_agent']["max_concurrent_requests"],
            score_type="bool",
        )

    def detect_zh(self, text, threshold=0.4):
        if text is None:
            return False
        # Remove URLs, numbers, and punctuation to focus on language characters
        cleaned_text = re.sub(r'[^\w\s]|[\d]', '', text)
        if not cleaned_text:
            return False

        # Count Chinese characters
        chinese_chars = re.findall(r'[\u4e00-\u9fa5]', cleaned_text)
        chinese_count = len(chinese_chars)

        # Count English characters
        english_chars = re.findall(r'[a-zA-Z]', cleaned_text)
        english_count = len(english_chars)

        # Total language characters
        total_chars = chinese_count + english_count
        if total_chars == 0:
            return False

        # Calculate ratios
        chinese_ratio = chinese_count / total_chars
        english_ratio = english_count / total_chars

        # Check if both languages exceed the threshold
        return chinese_ratio >= threshold

    def calc_content_coverage(self, 
                            batch_data_sources,
                            batch_solution_str,
                            batch_ground_truth):

        scores = []
        for sol, gt in zip(batch_solution_str, batch_ground_truth):
            if self.detect_zh(gt["document"]):
                lang_code = "zh"
            else:
                lang_code = "en"
            parsed = self.parse_solution_fn(sol)
            if parsed is None:
                scores.append(0.0)
                continue
            else:
                if lang_code == "en":
                    reconstruction = " ".join([_["content"] for _ in parsed])
                else:
                    reconstruction = "".join([_["content"] for _ in parsed])

                hyp_tokens = " ".join(tokenize(reconstruction, lang_code))
                ref_tokens = " ".join(tokenize(gt["document"], lang_code))
                sim_score = sacrebleu.sentence_bleu(
                    hyp_tokens, [ref_tokens]).score / 100
                scores.append(sim_score)
        
        return scores

    async def _compute_score(self,
                             batch_data_sources,
                             batch_solution_str,
                             batch_ground_truth,
                             ):
        def left_candidates(s, skip_run):
            return [x for i, x in enumerate(s) if i not in skip_run]

        # Full Scoring Pipeline
        final_results = [0.0 for _ in range(len(batch_solution_str))]
        skip_run = set()

        # Base Penalty
        penalty = defaultdict(list)
        for i, (data_source, solution_str, ground_truth) in enumerate(zip(batch_data_sources, batch_solution_str, batch_ground_truth)):
            parsed = self.parse_solution_fn(solution_str)
            if parsed is None: # Failure
                final_results[i] = self.min_reward
                skip_run.add(i)
            else:
                final_results[i] = 0.0

        scores = []
        for _ in range(len(batch_data_sources)):
            scores.append([])

        kill_results = await self.judge_with_kill_criteria(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
        )
        coverage_scores = self.calc_content_coverage(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
        )
        for i, (kill_result, coverage_score) in enumerate(zip(kill_results, coverage_scores)):
            if kill_result == 0.0:
                final_results[i] = 0.0
                skip_run.add(i)
            else:
                final_results[i] += (coverage_score / 10.0)

        named_processes = [
            Process(name="Atomicity", function=self.judge_atomicity, filter_only=False, non_skip=False),
            Process(name="Independency", function=self.judge_independency, filter_only=False, non_skip=False),
            Process(name="NLI", function=self.judge_nli, filter_only=False, non_skip=False),
            # Process(name="Fact", function=self.judge_fact_and_weight, filter_only=False, non_skip=False),
            # Process(name="QA", function=self.judge_qa_quality, filter_only=False, non_skip=False),
        ]

        for process in named_processes:  
            tmp_batch_data_sources, tmp_batch_solution_str, tmp_batch_ground_truth = left_candidates(batch_data_sources, skip_run), \
                    left_candidates(batch_solution_str, skip_run), left_candidates(batch_ground_truth, skip_run)
            idx_mapper = [i for i in range(len(batch_ground_truth)) if i not in skip_run]
            idx_mapper = {j: _ for j, _ in enumerate(idx_mapper)}

            process_eval = await process.function(
                tmp_batch_data_sources,
                tmp_batch_solution_str,
                tmp_batch_ground_truth,
            )
            for i, val in enumerate(process_eval):
                scores[idx_mapper[i]].append(val)

        minor_rewards = [""] * len(batch_solution_str)

        for k, score in enumerate(scores):
            if len(score) == 0:
                final_results[k] += 0
            else:
                parsed = self.parse_solution_fn(batch_solution_str[k])
                assert parsed is not None

                sizes = [len(_["content"]) for _ in parsed]
                size_weight = np.asarray(sizes) / np.linalg.norm(sizes, ord=1)
                
                base = np.asarray([1.0] * len(parsed))

                for m, partial_score in enumerate(score):
                    raw_score = partial_score * size_weight

                    if m == len(score) - 1:
                        partial_score = np.maximum(partial_score, [0.0 if ("qas" in _) and len(_["qas"]) else 1.0 for _ in parsed])

                    base = np.minimum(partial_score, base)
                    minor_rewards[k] += f'{named_processes[m].name}={np.sum(raw_score):.3f}|'
                real_score = np.sum(base * size_weight).tolist()
                final_results[k] += real_score
        
        for i in range(len(batch_solution_str)):
            cur_score = final_results[i]
            log_flag = f"[{self.task_name} VALID]" if self.split == "valid" else f"[{self.task_name} TRAIN]"
            if cur_score > 0 or (self.split == "valid" and random.random() < self.thought_log_prob) or (self.split == "train" and random.random() < self.thought_log_prob):
                log = True
            else:
                log = False
                
            if cur_score == self.min_reward and random.random() < self.thought_log_prob:
                log = True
                log_flag = f"[{self.task_name} VALID CORRUPT RESPONSE]" if self.split == "valid" else f"[{self.task_name} TRAIN CORRUPT RESPONSE]"

            if log:
                print(f'【Solution{i}】[{batch_ground_truth[i]["extra_info"]["domain"]}] [Final Reward]={cur_score:.3f}|{minor_rewards[i]}| ----- {self.log_solution(batch_solution_str[i], gt=batch_ground_truth[i])}')

        return final_results

    def log_solution(self, solution, **kwargs):
        gt = kwargs["gt"]
        norm = self.parse_solution_fn(solution)
        if norm is not None:
            return f'[REFINE]({len(norm)}) `{repr(json.dumps(norm, ensure_ascii=False))}`---------------  [RAW]({len(gt["document"])}) `{repr(gt["document"])}`'
        else:
            return repr(self.clip_string(solution))

