def cl_rewrite_parse_solution_fn(solution_str: str):
    if solution_str.count("</analysis>") > 1 or solution_str.count("<analysis>") > 1:
        return None

    if solution_str.count("</reconstruction>") > 1 or solution_str.count("<reconstruction>") > 1:
        return None

    if solution_str.count("</prev_chunk_id>") > 1 or solution_str.count("<prev_chunk_id>") > 1:
        return None

    if solution_str.count("</next_chunk_id>") > 1 or solution_str.count("<next_chunk_id>") > 1:
        return None

    solution_str = postprocess_solution(solution_str)
    if not solution_str.startswith("<think>"):
        solution_str = f'<think>\n{solution_str}'

    try:
        thought = re.findall(r'<think>.*</think>',
                             solution_str, re.DOTALL)[0]
    except Exception as err:
        return None

    solution_str = solution_str.replace(thought, "").strip()

    if (not solution_str.startswith("<analysis>")):
        return None

    if (not solution_str.endswith("</reconstruction>")):
        return None

    try:
        analysis = re.findall(r'<analysis>(.*)</analysis>',
                                solution_str, re.DOTALL)[0].strip()
    except Exception as err:
        return None

    try:
        reconstruction = re.findall(r'<reconstruction>(.*)</reconstruction>',
                                solution_str, re.DOTALL)[0].strip()
    except Exception as err:
        return None

    try:
        prev_chunk_id = re.findall(r'<prev_chunk_id>(.*)</prev_chunk_id>',
                                solution_str, re.DOTALL)[0].strip()
        prev_chunk_id = int(prev_chunk_id)
    except Exception as err:
        return None 

    try:
        next_chunk_id = re.findall(r'<next_chunk_id>(.*)</next_chunk_id>',
                                solution_str, re.DOTALL)[0].strip()
        next_chunk_id = int(next_chunk_id)
    except Exception as err:
        return None 

    # [0]分析 [1]completion [2]定位
    return analysis, reconstruction, (prev_chunk_id, next_chunk_id)


class CLRewriteComputeScore(Doc2QueryV3ComputeScore):
    def __init__(self,
                 parse_solution_fn,
                 split="train",
                 args=None,
                 min_reward=-2.0,
                 thought_log_prob=0.01,
                 ):
        super().__init__(
            parse_solution_fn=parse_solution_fn, split=split,
            args=args,
            min_reward=min_reward,
            thought_log_prob=thought_log_prob
        )
        self.task_name = "CL_REWRITE"

    def init_agent(self):
        self.agents = {}
        self.medium_reason_verify_agent = Agent(
            **self.args["medium_reason_verify_agent"]["model"])
        self.low_reason_verify_agent = Agent(
            **self.args["low_reason_verify_agent"]["model"])
            
    def detect_zh(self, text, threshold=0.4):
        if text is None:
            return False
        # Remove URLs, numbers, and punctuation to focus on language characters
        cleaned_text = re.sub(r'[^\w\s]|[\d]', '', text)
        if not cleaned_text:
            return False

        # Count Chinese characters
        chinese_chars = re.findall(r'[\u4e00-\u9fa5]', cleaned_text)
        chinese_count = len(chinese_chars)

        # Count English characters
        english_chars = re.findall(r'[a-zA-Z]', cleaned_text)
        english_count = len(english_chars)

        # Total language characters
        total_chars = chinese_count + english_count
        if total_chars == 0:
            return False

        # Calculate ratios
        chinese_ratio = chinese_count / total_chars
        english_ratio = english_count / total_chars

        # Check if both languages exceed the threshold
        return chinese_ratio >= threshold

    async def judge_similarity(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        return await self.judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=CLRewriteSimilarityJudge(),
            min_score=0.,
            max_score=1.0,
            eval_agent=self.medium_reason_verify_agent,
            max_concurrent_requests=self.args['medium_reason_verify_agent']["max_concurrent_requests"],
            score_type="float",
        )

    async def judge(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        eval_task,
        min_score,
        max_score,
        eval_agent,
        max_concurrent_requests,
        score_type="bool",
        judge_object=None,
    ):
        task = eval_task
        indices = []
        pairs = []

        for i, (gt, sol) in enumerate(zip(batch_ground_truth, batch_solution_str)):
            result = self.parse_solution_fn(sol)
            if result is not None:
                pairs.append((result[1], gt["completion"]))
                indices.append(i)
            else:
                continue

        repeat_pairs = pairs
        repeat_indices = indices

        qualities = await task.do_job(
            agent=eval_agent,
            batch_inputs=repeat_pairs,
            max_concurrent_requests=max_concurrent_requests,
        )

        scores = []
        for i in range(len(batch_solution_str)):
            scores.append([])
        for valid, index in zip(qualities, repeat_indices):
            if valid is None:
                pass
            else:
                if score_type == "bool":
                    _score = max_score if valid else min_score
                elif score_type == "float":
                    _score = valid
                else:
                    raise NotImplementedError(f'Invalid critique score type {score_type}')
                scores[index].append(_score)

        final_scores = [0.0] * len(batch_solution_str)
        for i, score in enumerate(scores):
            if len(score) == 0:
                final_scores[i] = 0.0
            else:
                final_scores[i] = min(score)
        return final_scores

    async def rubric_verify(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        results = await self._rubric_verify(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=CLRewriteRubricVerify(),
            min_score=0.0,
            max_score=0.1,
            eval_agent=self.medium_reason_verify_agent,
            max_concurrent_requests=self.args['medium_reason_verify_agent']["max_concurrent_requests"],
        )
        normed_scores = []
        for i, x in enumerate(results):
            base_score = 0
            if all(_ > 0 for _ in x):
                base_score = 1.0
            base_score += sum(x)
            normed_scores.append(base_score)
        return normed_scores

    async def _rubric_verify(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        eval_task,
        min_score,
        max_score,
        eval_agent,
        max_concurrent_requests,
        score_type="bool",
    ):
        task = eval_task
        indices = []
        pairs = []

        for i, (gt, sol) in enumerate(zip(batch_ground_truth, batch_solution_str)):
            result = self.parse_solution_fn(sol)
            if result is not None:
                for rubric in gt["rubrics"]:
                    pairs.append((result[1], rubric, gt["context"]))
                    indices.append(i)
            else:
                continue

        qualities = await task.do_job(
            agent=eval_agent,
            batch_inputs=pairs,
            max_concurrent_requests=max_concurrent_requests,
        )

        scores = []
        for i in range(len(batch_solution_str)):
            scores.append([])
        for valid, index in zip(qualities, indices):
            if valid is None:
                pass
            else:
                if score_type == "bool":
                    _score = max_score if valid else min_score
                elif score_type == "float":
                    _score = valid
                else:
                    raise NotImplementedError(f'Invalid critique score type {score_type}')
                scores[index].append(_score)

        return scores

    async def _compute_score(self,
                batch_data_sources,
                batch_solution_str,
                batch_ground_truth,
            ):

        final_results = [0.0] * len(batch_data_sources)
        
        llm_judge_similarity = await self.judge_similarity(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
        )
        rubric_verify_scores = await self.rubric_verify(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
        )
        
        for i, (data_source, solution_str, ground_truth) in enumerate(zip(batch_data_sources, batch_solution_str, batch_ground_truth)):
            parsed = self.parse_solution_fn(solution_str)
            if parsed is None: # Failure
                final_results[i] = self.min_reward
            else:
                analysis, reconstruction, predict_chunk_id = parsed
                prev_id, next_id = predict_chunk_id
                if prev_id == int(ground_truth["prev_chunk_id"]) and next_id == int(ground_truth["next_chunk_id"]):
                    if self.detect_zh(ground_truth["completion"]):
                        lang_code = "zh"
                    else:
                        lang_code = "en"

                    hyp_tokens = " ".join(tokenize(reconstruction, lang_code))
                    ref_tokens = " ".join(tokenize(ground_truth["completion"], lang_code))
                    sim_score = sacrebleu.sentence_bleu(
                        hyp_tokens, [ref_tokens]).score / 100
                    
                    final_results[i] = sim_score
                    final_results[i] += (llm_judge_similarity[i] + rubric_verify_scores[i])
                    final_results[i] += 1.0
                else:
                    final_results[i] = 0.0
                    if prev_id == int(ground_truth["prev_chunk_id"]):
                        final_results[i] += 0.5
                    if next_id == int(ground_truth["next_chunk_id"]):
                        final_results[i] += 0.5

            log_flag = f"[{self.task_name} VALID]" if self.split == "valid" else f"[{self.task_name} TRAIN]"

            cur_score = final_results[i]
            if cur_score > 0.815 or (self.split == "valid" and random.random() < self.thought_log_prob) or (self.split == "train" and random.random() < self.thought_log_prob):
                log = True
            else:
                log = False
            
            if cur_score == self.min_reward and (random.random() < self.thought_log_prob):
                log = True

            if log:
                print(f'【Solution{i}】[Final Reward]={cur_score:.3f} | BLEU={llm_judge_similarity[i]:.3f} | Rubrics={rubric_verify_scores[i]:.3f} | {self.log_chunk_id(solution_str, ground_truth)} | [REFINE] `{self.log_solution(solution_str)}`---------------  [RAW]`{repr(ground_truth["completion"])}`')
                print(f'【Analysis{i}】{self.log_analysis(solution_str)}')
        return final_results 

    def clip_string(self, s: str):
        if len(s) > 1500:
            return f'{s[:700]}... [省略] ...{s[-800:]}'
        return s

    def log_solution(self, solution, **kwargs):
        norm = self.parse_solution_fn(solution)
        if norm is None:
            return repr(self.clip_string(solution))
        return repr(norm[1])
    
    def log_chunk_id(self, solution, ground_truth):
        norm = self.parse_solution_fn(solution)
        if norm is None:
            return '[PARSE ERROR]'
        _prev, _next = norm[-1]
        return f'[PREV Pred{_prev}, Gold{ground_truth["prev_chunk_id"]}] [NEXT Pred{_next}, Gold{ground_truth["next_chunk_id"]}]'

    def log_analysis(self, solution, **kwargs):
        norm = self.parse_solution_fn(solution)
        if norm is None:
            return repr(self.clip_string(solution))
        return repr(norm[0])

