def cl_rewrite_rubrics_parse_solution_fn(solution_str: str):
    solution_str = postprocess_solution(solution_str)
    if not solution_str.startswith("<think>"):
        solution_str = f'<think>\n{solution_str}'

    try:
        thought = re.findall(r'<think>.*</think>',
                             solution_str, re.DOTALL)[0]
    except Exception as err:
        return None

    solution_str = solution_str.replace(thought, "").strip()

    if solution_str.count("```json") > 1:
        return solution_str

    try:
        solution_str = solution_str[solution_str.index("```json")+len("```json"):].strip()
    except Exception as err:
        return None

    try:
        solution_str = solution_str[:solution_str.index("```")].strip()
    except Exception as err:
        return None

    try:
        return json.loads(solution_str)
    except Exception as err:
        return None


class CLRewriteRubricsComputeScore(KDRewriteComputeScore):
    def __init__(self,
                 parse_solution_fn,
                 split="train",
                 args=None,
                 min_reward=-2.0,
                 thought_log_prob=0.01,
                 ):
        super().__init__(
            parse_solution_fn=parse_solution_fn, split=split,
            args=args,
            min_reward=min_reward,
            thought_log_prob=thought_log_prob
        )
        self.task_name = "CL_REWRITE_RUBRICS"

    def init_agent(self):
        self.agents = {}
        self.medium_reason_verify_agent = Agent(
            **self.args["medium_reason_verify_agent"]["model"])
        self.low_reason_verify_agent = Agent(
            **self.args["low_reason_verify_agent"]["model"])

    async def judge_rubrics_overlap(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None,
    ):
        return await self.full_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=CLRewriteRubricsOverlapJudge(),
            min_score=0.,
            max_score=1.0,
            eval_agent=self.medium_reason_verify_agent,
            max_concurrent_requests=self.args['medium_reason_verify_agent']["max_concurrent_requests"],
            score_type="bool",
            pair_parse_fn=lambda x, y: (json.dumps(x, ensure_ascii=False, indent="  "), None)
        )

    async def judge_single_rubric_quality(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        return await self.split_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=CLRewriteSingleRubricJudge(),
            min_score=-2.0,
            max_score=1.0,
            eval_agent=self.low_reason_verify_agent,
            max_concurrent_requests=self.args['low_reason_verify_agent']["max_concurrent_requests"],
            score_type="bool",
            gt_key="completion"
        )

    async def judge_single_rubric_match_completion(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        return await self.split_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=CLRewriteSingleRubricRecallJudge(),
            min_score=-2.0,
            max_score=1.0,
            eval_agent=self.low_reason_verify_agent,
            max_concurrent_requests=self.args['low_reason_verify_agent']["max_concurrent_requests"],
            score_type="bool",
            gt_key="completion"
        )

    async def judge_single_rubric_match_context(
        self,
        batch_data_sources,
        batch_solution_str,
        batch_ground_truth,
        skip_run=None
    ):
        return await self.split_refinement_judge(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
            eval_task=CLRewriteSingleRubricPrecisionJudge(),
            min_score=-2.0,
            max_score=1.0,
            eval_agent=self.medium_reason_verify_agent,
            max_concurrent_requests=self.args['medium_reason_verify_agent']["max_concurrent_requests"],
            score_type="bool",
            gt_key="input"
        )

    async def _compute_score(self,
                             batch_data_sources,
                             batch_solution_str,
                             batch_ground_truth,
                             ):
        def left_candidates(s, skip_run):
            return [x for i, x in enumerate(s) if i not in skip_run]

        # Full Scoring Pipeline
        final_results = [0.0 for _ in range(len(batch_solution_str))]
        skip_run = set()

        # Base Penalty
        penalty = defaultdict(list)
        for i, (data_source, solution_str, ground_truth) in enumerate(zip(batch_data_sources, batch_solution_str, batch_ground_truth)):
            parsed = self.parse_solution_fn(solution_str)
            if parsed is None: # Failure
                final_results[i] = self.min_reward
                skip_run.add(i)
            else:
                final_results[i] = 0.0

        scores = []
        for _ in range(len(batch_data_sources)):
            scores.append([])

        kill_results = await self.judge_rubrics_overlap(
            batch_data_sources,
            batch_solution_str,
            batch_ground_truth,
        )
        for i, kill_result in enumerate(kill_results):
            if kill_result == 0.0:
                final_results[i] = min(kill_result, final_results[i])
                skip_run.add(i)

        named_processes = [
            Process(name="Base", function=self.judge_single_rubric_quality, filter_only=False, non_skip=False),
            Process(name="Reference", function=self.judge_single_rubric_match_completion, filter_only=False, non_skip=False),
            Process(name="Context", function=self.judge_single_rubric_match_context, filter_only=False, non_skip=False),
        ]

        for process in named_processes:  
            tmp_batch_data_sources, tmp_batch_solution_str, tmp_batch_ground_truth = left_candidates(batch_data_sources, skip_run), \
                    left_candidates(batch_solution_str, skip_run), left_candidates(batch_ground_truth, skip_run)
            idx_mapper = [i for i in range(len(batch_ground_truth)) if i not in skip_run]
            idx_mapper = {j: _ for j, _ in enumerate(idx_mapper)}

            process_eval = await process.function(
                tmp_batch_data_sources,
                tmp_batch_solution_str,
                tmp_batch_ground_truth,
            )
            for i, val in enumerate(process_eval):
                scores[idx_mapper[i]].append(val)

        minor_rewards = [""] * len(batch_solution_str)

        for k, score in enumerate(scores):
            if len(score) == 0:
                final_results[k] += 0
            else:
                parsed = self.parse_solution_fn(batch_solution_str[k])
                assert parsed is not None
                
                base = np.asarray([1.0] * len(parsed))

                for m, partial_score in enumerate(score):
                    raw_score = partial_score

                    base = np.minimum(partial_score, base)
                    minor_rewards[k] += f'{named_processes[m].name}={np.sum(raw_score):.3f}|'
                real_score = np.sum(base).tolist()
                final_results[k] += max(real_score, 0.0) * 0.1
        
        for i in range(len(batch_solution_str)):
            cur_score = final_results[i]
            log_flag = f"[{self.task_name} VALID]" if self.split == "valid" else f"[{self.task_name} TRAIN]"
            if cur_score > 0 or (self.split == "valid" and random.random() < self.thought_log_prob) or (self.split == "train" and random.random() < self.thought_log_prob):
                log = True
            else:
                log = False
            # log = True
            if cur_score == self.min_reward and random.random() < self.thought_log_prob:
                log = True
                log_flag = f"[{self.task_name} VALID CORRUPT RESPONSE]" if self.split == "valid" else f"[{self.task_name} TRAIN CORRUPT RESPONSE]"

            if log:
                print(f'【Solution{i}】[Final Reward]={cur_score:.3f}|{minor_rewards[i]}| ----- {self.log_solution(batch_solution_str[i], gt=batch_ground_truth[i])}')

        return final_results

    def log_solution(self, solution, **kwargs):
        gt = kwargs["gt"]
        norm = self.parse_solution_fn(solution)
        if norm is not None:
            norm_str = " --- ".join([f'【{i}】「{_}」' for i, _ in enumerate(norm, start=1)])
            return f'[REFINE]({len(norm)}) `{repr(norm_str)}`---------------  [RAW]({len(gt["completion"])}) `{repr(gt["completion"])}`'
        else:
            return repr(self.clip_string(solution))


